create or replace function public.ensure_schoolpro_standard_assessment_schemes(p_school uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare n uuid;j uuid;s uuid;begin if not public.schoolpro_member_can_manage(p_school) then raise exception 'Not authorized';end if;
return jsonb_build_object('nursery_primary',n,'junior_secondary',j,'senior_secondary',s);end$$;revoke all on function public.ensure_schoolpro_standard_assessment_schemes(uuid) from public,anon;grant execute on function public.ensure_schoolpro_standard_assessment_schemes(uuid) to authenticated;